algorithms.pseudocode:
procedure CHECK_DLC(w, n):
    max_influence <- 0
    for each pair (i,j) with i < j:
        compute w11, w10, w01, w00
        if w11 * w00 > w10 * w01:
            return (false, infinity)
        influence_ij <- |Pr[Xi=1|Xj=1] - Pr[Xi=1|Xj=0]|
        max_influence <- max(max_influence, influence_ij)
    c <- max_i sum_{j!=i} |I(i,j)|
    T_mix <- n/(1-c) * ln(n/eps) if c < 1
    return (true, c, T_mix)
